//! History verbs: jj-style changes over immutable snapshots.
//!
//! `evolog` walks `Snapshot.predecessors` — the *rewrite* chain of one change — never
//! `parents`. `Store::evolog` follows `predecessors.first()`, which is exact as long as an
//! amend records exactly one predecessor (it does: [`Repo::amend`]).

use std::collections::BTreeMap;

use serde::{Deserialize, Serialize};
use svc_core::delta::Delta;
use svc_core::engine::status_report;
use svc_core::{
    ChangeId, ChangeSetId, EntityId, EntityRecord, Error, Intent, NoteKind, NoteTo, ObservedClass,
    Op, OpIx, OpLogEntry, RelPath, Result, Snapshot, SnapshotId, Timestamp, View,
};

use crate::repo::{Mutation, Repo};
use crate::workspace::DEFAULT_WORKSPACE;

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct ChangeOut {
    pub change: ChangeId,
    pub short: String,
    pub snapshot: SnapshotId,
    pub message: String,
    pub branches: Vec<String>,
    pub current: bool,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct OpOut {
    pub ix: OpIx,
    pub op: Op,
    pub declared: Option<Intent>,
    pub observed: Option<ObservedClass>,
    pub flagged: bool,
    pub at: Timestamp,
    pub group: Option<ChangeSetId>,
    pub root_after: SnapshotId,
    /// The entity's name *before* the op (renames need it; the current snapshot has the new one).
    pub subject: Option<String>,
    /// The checkout that made it (absent = the default one).
    #[serde(default)]
    pub workspace: Option<String>,
}

/// How one op or rewrite touched one entity. `Edited.observed` is the op log's verdict
/// for that op, absent when nothing classified it (a hand edit, or a class not yet landed).
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum Touch {
    Added,
    Removed,
    Renamed { from: String, to: String },
    Moved { from: Option<EntityId>, to: Option<EntityId> },
    Relocated { from: (RelPath, u32), to: (RelPath, u32) },
    Edited { observed: Option<ObservedClass> },
    /// Same text, different meaning: the bindings resolve differently because another
    /// entity changed, or because the analyser did. Not a hand edit.
    Rebound,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct EntityTouch {
    pub entity: EntityId,
    pub name: String,
    pub touch: Touch,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct EvologEntry {
    pub snapshot: SnapshotId,
    pub message: String,
    pub entities: usize,
    /// Versus the previous (older) entry; empty for the first.
    pub deltas: Vec<EntityTouch>,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct BlameEntry {
    pub ix: OpIx,
    pub change: ChangeId,
    pub op: Op,
    pub touch: Touch,
    pub at: Timestamp,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct MutationOut {
    pub ix: OpIx,
    pub change: ChangeId,
    pub snapshot: SnapshotId,
    pub closed_stale_changeset: Option<ChangeSetId>,
}

impl MutationOut {
    fn of(repo: &Repo, m: Mutation) -> Result<Self> {
        Ok(Self {
            ix: m.ix,
            change: repo.store().get_snapshot(m.entry.after.root)?.change,
            snapshot: m.snapshot,
            closed_stale_changeset: m.closed_stale_changeset,
        })
    }
}

fn op_out(repo: &Repo, ix: OpIx, e: &OpLogEntry) -> OpOut {
    let store = repo.store();
    // Name as of just before the op (so a rename shows its old name); for ops that create
    // the entity (add-def, extract) fall back to the name just after. Stored on the entry
    // so the line stays readable after the entity is later deleted or the op undone.
    let subject = op_entity(&e.op).and_then(|id| {
        let name_in = |root| {
            store
                .get_snapshot(root)
                .ok()
                .and_then(|s| s.entities.get(&id).map(|r| r.name.clone()))
        };
        name_in(e.before.root).or_else(|| name_in(e.after.root))
    });
    OpOut {
        ix,
        subject,
        declared: e.declared().cloned(),
        observed: e.observed,
        flagged: e.flagged(),
        at: e.at,
        group: e.group,
        root_after: e.after.root,
        op: e.op.clone(),
        workspace: repo.redb().op_workspace(ix).ok().flatten().filter(|w| !w.is_empty()),
    }
}

pub(crate) fn child_of(cur: &Snapshot, cur_id: SnapshotId, change: ChangeId) -> Snapshot {
    Snapshot {
        parents: vec![cur_id],
        predecessors: Vec::new(),
        change,
        entities: cur.entities.clone(),
        files: cur.files.clone(),
        conflicts: cur.conflicts.clone(),
        message: String::new(),
    }
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct StatusOut {
    pub summary: String,
    pub entities: usize,
    pub layout: usize,
    pub semantic: usize,
    pub clean: bool,
    pub change: ChangeId,
    pub snapshot: SnapshotId,
    /// Semantic deltas versus the snapshot before this status (layout-only ordinal shifts suppressed).
    pub deltas: Vec<Delta>,
    pub absorbed: bool,
    /// Unresolved merge conflicts on the current snapshot (`svc conflicts` lists them).
    pub conflicts: usize,
    /// Other checkouts' live claims on entities in this tree (`svc claim`).
    #[serde(default)]
    pub claims: Vec<ClaimOut>,
    /// Unread mail/review notes addressed here or `@all`.
    #[serde(default)]
    pub inbox: usize,
    /// Entities whose text is unchanged but whose bindings now read differently; not edits.
    #[serde(default)]
    pub rebound: usize,
}

/// `svc status`: absorb hand edits into the current change (recording an `Absorb` op) and
/// report what changed. Identical content is a no-op.
pub fn status(repo: &Repo) -> Result<StatusOut> {
    let (report, snap, absorbed) = match repo.absorb()? {
        Some((prev, id)) => {
            let next = repo.store().get_snapshot(id)?;
            (status_report(repo.store(), &prev, &next)?, next, true)
        }
        None => {
            let cur = repo.current()?;
            (status_report(repo.store(), &cur, &cur)?, cur, false)
        }
    };
    Ok(StatusOut {
        summary: report.summary(),
        entities: report.entities,
        layout: report.layout,
        semantic: report.semantic,
        clean: report.deltas.is_empty(),
        change: snap.change,
        snapshot: snap.id(),
        deltas: report.deltas,
        absorbed,
        conflicts: snap.conflicts.len(),
        claims: active_claims(repo)?,
        inbox: inbox(repo)?.unread.len(),
        rebound: report.rebound,
    })
}

/// `svc new`: start the next change on top of the current one.
pub fn new(repo: &Repo) -> Result<MutationOut> {
    let change = ChangeId::new();
    let m = repo.mutate(Op::New { change }, None, |repo, cur| {
        repo.commit_snapshot(&child_of(cur, cur.id(), change))
    })?;
    MutationOut::of(repo, m)
}

/// `svc describe`: set the current change's message (an amend).
pub fn describe(repo: &Repo, msg: &str) -> Result<MutationOut> {
    let m = repo.mutate(Op::Describe { msg: msg.into() }, None, |repo, cur| {
        let mut next = cur.clone();
        next.message = msg.into();
        repo.amend(cur, next)
    })?;
    MutationOut::of(repo, m)
}

/// `svc branch <name>`: a new change that is a *sibling* of the current one — its parent is
/// the current change's parent — named `name`, and made current. A root
/// change has no parent, so its sibling would be empty; branch from the root itself instead.
pub fn branch(repo: &Repo, name: &str) -> Result<MutationOut> {
    if repo.store().branch(name)?.is_some() {
        return Err(Error::Other(format!("branch {name:?} already exists")));
    }
    let change = ChangeId::new();
    let m = repo.mutate(Op::Branch { name: name.into() }, None, |repo, cur| {
        let (base, base_id) = match cur.parents.first() {
            Some(p) => (repo.store().get_snapshot(*p)?, *p),
            None => (cur.clone(), cur.id()),
        };
        let id = repo.commit_snapshot(&child_of(&base, base_id, change))?;
        repo.store().set_branch(name, change)?;
        Ok(id)
    })?;
    MutationOut::of(repo, m)
}

/// `svc edit <change|branch>`: make another change's head the working copy.
pub fn edit(repo: &Repo, target: &str) -> Result<View> {
    let change = repo.resolve_change(target)?;
    let head = repo.store().head(change)?;
    checkout(repo, head)
}

/// `svc checkout <snapshot>`: view a snapshot. Moves `root` only — no change, no head, no
/// op-log entry — and refuses to overwrite hand edits.
pub fn checkout(repo: &Repo, snapshot: SnapshotId) -> Result<View> {
    if !repo.working_copy_clean()? {
        return Err(Error::Other(
            "working copy has edits not yet snapshotted; run `svc status` first".into(),
        ));
    }
    let snap = repo.store().get_snapshot(snapshot)?;
    repo.store().set_render_pending(true)?;
    repo.store().set_root(snapshot)?;
    repo.render_to_disk(&snap)?;
    repo.store().set_render_pending(false)?;
    repo.view()
}

/// `svc heads`: every change and where it points, current first.
pub fn heads(repo: &Repo) -> Result<Vec<ChangeOut>> {
    let store = repo.store();
    let current = repo.current_change()?;
    let mut names: BTreeMap<ChangeId, Vec<String>> = BTreeMap::new();
    for (name, id) in store.branches()? {
        names.entry(id).or_default().push(name);
    }
    let mut out = Vec::new();
    for (change, snapshot) in store.heads()? {
        out.push(ChangeOut {
            change,
            short: change.short(),
            snapshot,
            message: store.get_snapshot(snapshot)?.message,
            branches: names.remove(&change).unwrap_or_default(),
            current: change == current,
        });
    }
    out.sort_by_key(|c| !c.current);
    Ok(out)
}

/// `svc op log`: the unscoped journal, newest first.
pub fn op_log(repo: &Repo) -> Result<Vec<OpOut>> {
    Ok(repo
        .store()
        .ops(OpIx(0), true)?
        .iter()
        .map(|(ix, e)| op_out(repo, *ix, e))
        .collect())
}

/// `svc log`: the op view scoped to one change — every op that moved that
/// change's head or ran on it (a no-op `edit-def` still happened and still queues for
/// review) — newest first. Defaults to the current change.
pub fn log(repo: &Repo, change: Option<ChangeId>) -> Result<Vec<OpOut>> {
    let change = match change {
        Some(c) => c,
        None => repo.current_change()?,
    };
    let store = repo.store();
    let on_change = |e: &OpLogEntry| {
        e.before.heads.get(&change) != e.after.heads.get(&change)
            || store.get_snapshot(e.after.root).is_ok_and(|s| s.change == change)
    };
    Ok(store
        .ops(OpIx(0), true)?
        .iter()
        .filter(|(_, e)| on_change(e))
        // The change's birth is not one of its events.
        .filter(|(_, e)| !matches!(e.op, Op::New { .. } | Op::Branch { .. }))
        .map(|(ix, e)| op_out(repo, *ix, e))
        .collect())
}

/// `svc log <entity>`: blame at entity granularity — which ops touched it and how.
pub fn blame(repo: &Repo, entity: EntityId) -> Result<Vec<BlameEntry>> {
    let store = repo.store();
    let mut out = Vec::new();
    for (ix, e) in store.ops(OpIx(0), true)? {
        if e.before.root == e.after.root {
            continue;
        }
        let before = store.get_snapshot(e.before.root)?;
        let after = store.get_snapshot(e.after.root)?;
        if let Some(touch) = touch(
            before.entities.get(&entity),
            after.entities.get(&entity),
            e.observed,
        ) {
            out.push(BlameEntry {
                ix,
                change: after.change,
                op: e.op.clone(),
                touch,
                at: e.at,
            });
        }
    }
    Ok(out)
}

/// `svc evolog <change>`: the change's snapshots newest first, each with what it changed
/// versus the one it rewrote.
pub fn evolog(repo: &Repo, change: ChangeId) -> Result<Vec<EvologEntry>> {
    let store = repo.store();
    let snaps = store.evolog(change)?;
    let ops = store.ops(OpIx(0), false)?;
    let mut out = Vec::with_capacity(snaps.len());
    for (i, snap) in snaps.iter().enumerate() {
        let id = snap.id();
        let observed = ops
            .iter()
            .find(|(_, e)| e.after.heads.get(&change) == Some(&id))
            .and_then(|(_, e)| e.observed);
        let deltas = match snaps.get(i + 1) {
            Some(prev) => touches(prev, snap, observed),
            None => Vec::new(),
        };
        out.push(EvologEntry {
            snapshot: id,
            message: snap.message.clone(),
            entities: snap.entities.len(),
            deltas,
        });
    }
    Ok(out)
}

/// `svc undo`: restore the view from before this checkout's newest op that no earlier undo
/// already reverted; an op that belongs to a changeset takes the whole group with it.
/// Redo is `svc op restore <n>`.
pub fn undo(repo: &Repo) -> Result<MutationOut> {
    // Each checkout undoes its own ops: another checkout's entry carries
    // *its* root in `before`, and restoring that here would silently switch checkouts.
    // Unattributed entries from before op attribution count as the default checkout's.
    let ops = repo.redb().own_ops(OpIx(0), true)?;
    // Repeated `undo` keeps walking back (as `jj undo` does since 0.29) instead of undoing
    // the previous undo: skip every op an earlier undo already reverted. An undo of a
    // changeset reverts the whole group, so it cancels that many ops.
    let entries: Vec<&OpLogEntry> = ops.iter().map(|(_, e)| e).collect(); // newest first
    let mut i = 0;
    let mut pending = 0usize;
    let first = loop {
        let Some(e) = entries.get(i) else {
            return Err(Error::Other("nothing to undo".into()));
        };
        if matches!(e.op, Op::Undo) {
            pending += 1;
            i += 1;
        } else if pending > 0 {
            // reverted by an earlier undo — together with the rest of its changeset
            pending -= 1;
            let g = e.group;
            i += 1;
            while g.is_some() && entries.get(i).is_some_and(|n| n.group == g) {
                i += 1;
            }
        } else {
            break i;
        }
    };
    let last = entries[first];
    let target = match last.group {
        Some(g) => entries[first..]
            .iter()
            .take_while(|e| e.group == Some(g))
            .last()
            .copied()
            .unwrap_or(last),
        None => last,
    };
    if target.before.heads.is_empty() {
        return Err(Error::Other("cannot undo init".into()));
    }
    // Only what the undone ops moved goes back: this checkout's root and the heads whose
    // value differs across the range. Another checkout's head that moved since is its
    // business, not something an undo here may rewind.
    let mut view = repo.view()?;
    view.root = target.before.root;
    for (change, snap) in &target.before.heads {
        if last.after.heads.get(change) != Some(snap) {
            view.heads.insert(*change, *snap);
        }
    }
    let m = repo.restore_view(&view, Op::Undo)?;
    MutationOut::of(repo, m)
}

/// `svc op restore <n>`: return to the view as it stood right after op `n`.
pub fn op_restore(repo: &Repo, ix: OpIx) -> Result<MutationOut> {
    let entry = repo
        .store()
        .ops(ix, false)?
        .into_iter()
        .find(|(i, _)| *i == ix)
        .map(|(_, e)| e)
        .ok_or_else(|| Error::NotFound(format!("op {}", ix.0)))?;
    let m = repo.restore_view(&entry.after, Op::Restore { at: ix.0 })?;
    MutationOut::of(repo, m)
}

/// Attribute-level difference of one entity between two snapshots. Content that moved
/// without any attribute moving is `Edited`.
pub fn touch(
    prev: Option<&EntityRecord>,
    next: Option<&EntityRecord>,
    observed: Option<ObservedClass>,
) -> Option<Touch> {
    match (prev, next) {
        (None, None) => None,
        (None, Some(_)) => Some(Touch::Added),
        (Some(_), None) => Some(Touch::Removed),
        (Some(a), Some(b)) => {
            if a.name != b.name {
                Some(Touch::Renamed {
                    from: a.name.clone(),
                    to: b.name.clone(),
                })
            } else if a.parent != b.parent {
                Some(Touch::Moved {
                    from: a.parent,
                    to: b.parent,
                })
            } else if a.file != b.file || a.ordinal != b.ordinal {
                Some(Touch::Relocated {
                    from: (a.file.clone(), a.ordinal),
                    to: (b.file.clone(), b.ordinal),
                })
            } else if a.bytes == b.bytes && a.content != b.content {
                Some(Touch::Rebound)
            } else if a.content != b.content || a.bytes != b.bytes {
                Some(Touch::Edited { observed })
            } else {
                None
            }
        }
    }
}

/// Every entity `touch`ed between two snapshots, in id order.
pub fn touches(prev: &Snapshot, next: &Snapshot, observed: Option<ObservedClass>) -> Vec<EntityTouch> {
    let ids = prev.entities.keys().chain(next.entities.keys());
    let mut seen = std::collections::BTreeSet::new();
    let mut out = Vec::new();
    for id in ids {
        if !seen.insert(*id) {
            continue;
        }
        let a = prev.entities.get(id);
        let b = next.entities.get(id);
        if let Some(t) = touch(a, b, observed) {
            out.push(EntityTouch {
                entity: *id,
                name: b.or(a).map(|r| r.name.clone()).unwrap_or_default(),
                touch: t,
            });
        }
    }
    out
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct ChangeSetOut {
    pub id: ChangeSetId,
    pub name: String,
    pub intent: Intent,
    pub description: String,
    pub open: bool,
    pub ops: Vec<OpOut>,
    /// Review/mail notes hung on this changeset (the other half of a PR).
    #[serde(default)]
    pub reviews: Vec<OpOut>,
}

/// `svc changeset begin <name>`: open a group that every following op is stamped with.
/// Refuses while another is open unless `force`; a stale row is closed first.
pub fn changeset_begin(
    repo: &Repo,
    name: &str,
    intent: Intent,
    pid: Option<u32>,
    force: bool,
) -> Result<ChangeSetOut> {
    let store = repo.store();
    if let (Some(open), _) = repo.open_group()? {
        if !force {
            return Err(Error::Other(format!(
                "changeset {} is already open; `svc changeset end` it or pass --force",
                open.short()
            )));
        }
    }
    let cs = svc_core::ChangeSet {
        id: ChangeSetId::new(),
        name: name.into(),
        intent,
        queue: Vec::new(),
        description: String::new(),
    };
    store.put_changeset(&cs)?;
    store.set_open_changeset(Some(svc_core::OpenChangeSet {
        id: cs.id,
        pid,
        opened_at: crate::repo::now(),
    }))?;
    changeset_out(repo, cs, true)
}

/// `svc changeset end`: close the open group. Returns what was closed, if anything.
pub fn changeset_end(repo: &Repo) -> Result<Option<ChangeSetId>> {
    let open = repo.store().open_changeset()?.map(|r| r.id);
    repo.store().set_open_changeset(None)?;
    Ok(open)
}

/// `svc changeset reopen <id>`: make an existing group the open one again, so more ops
/// (a follow-up, a reviewer's fix) join it. Refuses while another group is open.
pub fn changeset_reopen(repo: &Repo, id: ChangeSetId) -> Result<ChangeSetOut> {
    let store = repo.store();
    let cs = store.get_changeset(id)?;
    if let (Some(open), _) = repo.open_group()? {
        if open != id {
            return Err(Error::Other(format!(
                "changeset {} is already open; `svc changeset end` it first",
                open.short()
            )));
        }
    }
    store.set_open_changeset(Some(svc_core::OpenChangeSet { id, pid: None, opened_at: crate::repo::now() }))?;
    changeset_out(repo, cs, true)
}

/// `svc changeset status`: the open group and its ops so far, or `None`.
pub fn changeset_status(repo: &Repo) -> Result<Option<ChangeSetOut>> {
    match repo.open_group()? {
        (Some(id), _) => changeset_out(repo, repo.store().get_changeset(id)?, true).map(Some),
        _ => Ok(None),
    }
}

/// `svc changesets`: every group, with its ops.
pub fn changesets(repo: &Repo) -> Result<Vec<ChangeSetOut>> {
    let open = repo.open_group()?.0;
    repo.store()
        .changesets()?
        .into_iter()
        .map(|cs| {
            let is_open = open == Some(cs.id);
            changeset_out(repo, cs, is_open)
        })
        .collect()
}

fn changeset_out(repo: &Repo, cs: svc_core::ChangeSet, open: bool) -> Result<ChangeSetOut> {
    let mut ops = Vec::new();
    let mut reviews = Vec::new();
    for (ix, e) in repo.store().ops(OpIx(0), true)? {
        let about = matches!(
            &e.op,
            Op::Note {
                to: NoteTo::Changeset(id),
                kind,
                ..
            } if *id == cs.id && !matches!(kind, NoteKind::Claim | NoteKind::Release)
        );
        if e.group == Some(cs.id) || about {
            let out = op_out(repo, ix, &e);
            if about {
                reviews.push(out.clone());
            }
            ops.push(out);
        }
    }
    Ok(ChangeSetOut {
        id: cs.id,
        name: cs.name,
        intent: cs.intent,
        description: cs.description,
        open,
        ops,
        reviews,
    })
}

/// Resolve an entity by name in the current snapshot, optionally qualified as
/// `Parent::name` (one level) to disambiguate methods of the same name.
/// `svc … --entity X`: an id, a name, `Parent::name` (the parent's name, or for an impl
/// block the type it is for), or `path/suffix.rs:name`. Ambiguity lists the candidates.
pub fn resolve_entity(repo: &Repo, arg: &str) -> Result<EntityId> {
    resolve_entity_in(&repo.current()?, arg)
}

/// [`resolve_entity`] against a chosen snapshot (a historical `--at`). An id or an id
/// prefix wins outright; names are matched exactly.
pub fn resolve_entity_in(snap: &Snapshot, arg: &str) -> Result<EntityId> {
    if let Some(id) = parse_entity_id(arg) {
        if snap.entities.contains_key(&id) {
            return Ok(id);
        }
    }
    let spec_hits: Vec<EntityId> = snap.entities.keys().copied().filter(|id| id.matches_spec(arg)).collect();
    let (file, rest) = match arg.rsplit_once(':').filter(|(f, _)| f.contains('/') || f.contains('.')) {
        Some((f, n)) if !f.ends_with(':') => (Some(f), n),
        _ => (None, arg),
    };
    let (parent, name) = match rest.rsplit_once("::") {
        Some((p, n)) => (Some(p), n),
        None => (None, rest),
    };
    let mut hits: Vec<EntityId> = snap
        .entities
        .iter()
        .filter(|(_, r)| r.name == name)
        .filter(|(_, r)| file.is_none_or(|f| r.file.as_str().ends_with(f)))
        .filter(|(_, r)| match parent {
            None => true,
            Some(p) => r
                .parent
                .and_then(|pid| snap.entities.get(&pid))
                .is_some_and(|pr| pr.name == p || impl_target(&pr.name) == Some(p)),
        })
        .map(|(id, _)| *id)
        .collect();
    hits.sort();
    match hits.len() {
        1 => Ok(hits[0]),
        0 if spec_hits.len() == 1 => Ok(spec_hits[0]),
        0 => Err(Error::NotFound(format!("entity {arg:?}"))),
        _ => {
            let listed: Vec<String> = hits
                .iter()
                .map(|id| {
                    let r = &snap.entities[id];
                    let parent = r
                        .parent
                        .and_then(|p| snap.entities.get(&p))
                        .map(|p| format!("{}::", impl_target(&p.name).unwrap_or(&p.name)))
                        .unwrap_or_default();
                    format!("{}:{parent}{} ⟨{}⟩", r.file, r.name, id.short())
                })
                .collect();
            Err(Error::Other(format!(
                "{arg:?} names {} entities — {}; qualify it as Parent::{name} or file.rs:{name}, or pass the id",
                hits.len(),
                listed.join(", ")
            )))
        }
    }
}

/// The type an impl block's synthesised name is for: `impl<Foo>` and `impl<Tr for Foo>` → `Foo`.
fn impl_target(name: &str) -> Option<&str> {
    let inner = name.strip_prefix("impl<")?.strip_suffix('>')?;
    Some(inner.rsplit_once(" for ").map_or(inner, |(_, t)| t))
}

pub fn parse_entity_id(s: &str) -> Option<EntityId> {
    s.parse::<uuid::Uuid>().ok().map(EntityId)
}

/// The entity an op is about, when it is about one.
pub fn op_entity(op: &Op) -> Option<EntityId> {
    match op {
        Op::Rename { id, .. }
        | Op::Move { id, .. }
        | Op::Relocate { id, .. }
        | Op::Extract { id, .. }
        | Op::Inline { id }
        | Op::AddDef { id, .. }
        | Op::Delete { id, .. }
        | Op::EditDef { id, .. } => Some(*id),
        Op::Note {
            to: NoteTo::Entity(id),
            ..
        } => Some(*id),
        _ => None,
    }
}

/// Whole-word mentions of `word` still in the rendered working copy after a rename. Every
/// reference svc resolved has already changed; what remains is what it could not resolve —
/// method calls on typed receivers (`x.word(…)`, which need types), and strings, comments
/// or unrelated bindings — and did not touch. The honest numbers to print next to
/// "renamed" (demo line 13), not to hide.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct Mentions {
    pub method_calls: usize,
    pub other: usize,
}

pub fn untracked_mentions(repo: &Repo, word: &str) -> Result<Mentions> {
    let snap = repo.current()?;
    let is_ident = |c: char| c == '_' || c.is_ascii_alphanumeric();
    let mut m = Mentions::default();
    for path in snap.files.keys() {
        let Ok(text) = std::fs::read_to_string(repo.root_dir().join(path.as_str())) else {
            continue;
        };
        let mut from = 0;
        while let Some(i) = text[from..].find(word) {
            let start = from + i;
            let end = start + word.len();
            from = end;
            let head = &text[..start];
            let tail = &text[end..];
            if head.chars().next_back().is_some_and(is_ident) || tail.chars().next().is_some_and(is_ident) {
                continue;
            }
            let method_call = head.trim_end().ends_with('.') && tail.trim_start().starts_with('(');
            if method_call {
                m.method_calls += 1;
            } else {
                m.other += 1;
            }
        }
    }
    Ok(m)
}

/// The checkout name stamped on notes and matched by the inbox: the workspace name; for
/// the `.svc/` tree itself `SVC_CHECKOUT` if set, else the directory's name — so mail
/// between stores names its sender without a shared registry.
pub fn checkout_name(repo: &Repo) -> String {
    if let Some(name) = repo.workspace() {
        return name.to_string();
    }
    if let Ok(name) = std::env::var("SVC_CHECKOUT")
        && !name.trim().is_empty()
    {
        return name;
    }
    repo.root_dir()
        .file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .filter(|n| !n.is_empty())
        .unwrap_or_else(|| DEFAULT_WORKSPACE.to_string())
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct ClaimOut {
    pub entity: EntityId,
    pub name: String,
    pub by: String,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct InboxOut {
    pub unread: Vec<OpOut>,
    pub cursor: u64,
}

/// Append a coordination op. Snapshot is unchanged; the log is the mailbox.
pub fn note(repo: &Repo, to: NoteTo, kind: NoteKind, text: impl Into<String>) -> Result<MutationOut> {
    let text = text.into();
    if matches!(kind, NoteKind::Note) && text.trim().is_empty() {
        return Err(Error::Other("note text is empty".into()));
    }
    // Hand edits absorbed on the way are the tree's own story, stamped now and outside
    // the open changeset: a mail changeset must stay pushable to a hub on another tree.
    let own = crate::repo::Provenance { at: crate::repo::now(), group: None, workspace: repo.workspace().map(str::to_string) };
    repo.with_provenance(own, || repo.absorb().map(|_| ()))?;
    let m = repo.mutate(
        Op::Note { to, kind, text },
        None,
        |_, cur| Ok(cur.id()),
    )?;
    MutationOut::of(repo, m)
}

pub fn resolve_changeset(repo: &Repo, spec: &str) -> Result<svc_core::ChangeSet> {
    let all = repo.store().changesets()?;
    let named: Vec<_> = all.iter().filter(|c| c.name == spec).cloned().collect();
    match named.len() {
        1 => return Ok(named.into_iter().next().unwrap()),
        n if n > 1 => {
            return Err(Error::Other(format!(
                "changeset {spec:?} names {n} groups — pass the id"
            )));
        }
        _ => {}
    }
    match svc_core::ids::resolve_spec(all.iter().map(|c| c.id), |id| {
        id.matches_spec(spec) || id.to_string() == spec
    }) {
        Ok(id) => all
            .into_iter()
            .find(|c| c.id == id)
            .ok_or_else(|| Error::NotFound(format!("changeset {spec:?}"))),
        Err(hits) if hits.is_empty() => Err(Error::NotFound(format!("changeset {spec:?}"))),
        Err(_) => Err(Error::Other(format!(
            "changeset {spec:?} is ambiguous — pass more of the id"
        ))),
    }
}

pub fn changeset_show(repo: &Repo, spec: &str) -> Result<ChangeSetOut> {
    let cs = resolve_changeset(repo, spec)?;
    let open = repo.open_group()?.0 == Some(cs.id);
    changeset_out(repo, cs, open)
}

/// `svc review <changeset> --approve|--request-changes|--note`.
pub fn review(
    repo: &Repo,
    spec: &str,
    kind: NoteKind,
    text: &str,
) -> Result<MutationOut> {
    if !matches!(
        kind,
        NoteKind::Approve | NoteKind::RequestChanges | NoteKind::Note
    ) {
        return Err(Error::Other("review kind must be approve, request-changes, or note".into()));
    }
    let cs = resolve_changeset(repo, spec)?;
    note(repo, NoteTo::Changeset(cs.id), kind, text)
}

/// `svc mail <checkout|@all> "<text>" [--about entity|changeset]`.
pub fn mail(
    repo: &Repo,
    to: &str,
    text: &str,
    about: Option<&str>,
) -> Result<MutationOut> {
    let dest = resolve_mail_to(repo, to, about)?;
    note(repo, dest, NoteKind::Note, text)
}

fn resolve_mail_to(repo: &Repo, to: &str, about: Option<&str>) -> Result<NoteTo> {
    if let Some(about) = about {
        if let Ok(id) = resolve_entity(repo, about) {
            return Ok(NoteTo::Entity(id));
        }
        if let Ok(cs) = resolve_changeset(repo, about) {
            return Ok(NoteTo::Changeset(cs.id));
        }
        return Err(Error::NotFound(format!(
            "--about {about:?} is not an entity or a changeset"
        )));
    }
    if to == "@all" {
        Ok(NoteTo::All)
    } else {
        Ok(NoteTo::Checkout(to.into()))
    }
}

fn note_is_mail(op: &Op) -> bool {
    match op {
        Op::Note { kind, .. } => !matches!(kind, NoteKind::Claim | NoteKind::Release),
        _ => false,
    }
}

fn note_addressed_to(op: &Op, me: &str) -> bool {
    match op {
        Op::Note { to, .. } => match to {
            NoteTo::All => true,
            NoteTo::Checkout(name) => name == me,
            NoteTo::Changeset(_) | NoteTo::Entity(_) => true,
        },
        _ => false,
    }
}

pub fn inbox(repo: &Repo) -> Result<InboxOut> {
    let me = checkout_name(repo);
    let cursor = repo.redb().inbox_read_ix()?;
    let unread = repo
        .store()
        .ops(OpIx(0), false)?
        .into_iter()
        .filter(|(ix, e)| {
            ix.0 > cursor && note_is_mail(&e.op) && note_addressed_to(&e.op, &me)
        })
        .map(|(ix, e)| op_out(repo, ix, &e))
        .collect();
    Ok(InboxOut { unread, cursor })
}

/// `svc mail --read <n>`: mark notes through op `n` as read.
pub fn mail_read(repo: &Repo, ix: u64) -> Result<InboxOut> {
    repo.redb().set_inbox_read_ix(ix)?;
    inbox(repo)
}

fn claim_ids(repo: &Repo, spec: &str) -> Result<Vec<EntityId>> {
    if let Ok(id) = resolve_entity(repo, spec) {
        return Ok(vec![id]);
    }
    let snap = repo.current()?;
    let ids: Vec<EntityId> = snap
        .entities
        .iter()
        .filter(|(_, r)| r.file.as_str() == spec || r.file.as_str().ends_with(&format!("/{spec}")))
        .map(|(id, _)| *id)
        .collect();
    if ids.is_empty() {
        Err(Error::NotFound(format!(
            "{spec:?} is not an entity or a tracked file"
        )))
    } else {
        Ok(ids)
    }
}

pub fn claim(repo: &Repo, specs: &[String]) -> Result<Vec<MutationOut>> {
    if specs.is_empty() {
        return Err(Error::Other("claim: pass an entity or a file".into()));
    }
    let me = checkout_name(repo);
    let mut out = Vec::new();
    for spec in specs {
        for id in claim_ids(repo, spec)? {
            out.push(note(
                repo,
                NoteTo::Entity(id),
                NoteKind::Claim,
                me.clone(),
            )?);
        }
    }
    Ok(out)
}

pub fn release(repo: &Repo, specs: &[String]) -> Result<Vec<MutationOut>> {
    let me = checkout_name(repo);
    let ids = if specs.is_empty() {
        active_claims(repo)?
            .into_iter()
            .filter(|c| c.by == me)
            .map(|c| c.entity)
            .collect()
    } else {
        let mut ids = Vec::new();
        for spec in specs {
            ids.extend(claim_ids(repo, spec)?);
        }
        ids
    };
    let mut out = Vec::new();
    for id in ids {
        out.push(note(
            repo,
            NoteTo::Entity(id),
            NoteKind::Release,
            me.clone(),
        )?);
    }
    Ok(out)
}

/// Latest Claim/Release per entity; only live Claims remain.
pub fn active_claims(repo: &Repo) -> Result<Vec<ClaimOut>> {
    let mut last: BTreeMap<EntityId, (NoteKind, String)> = BTreeMap::new();
    for (ix, e) in repo.store().ops(OpIx(0), false)? {
        if let Op::Note {
            to: NoteTo::Entity(id),
            kind,
            ..
        } = &e.op
        {
            if matches!(kind, NoteKind::Claim | NoteKind::Release) {
                let by = repo
                    .redb()
                    .op_workspace(ix)
                    .ok()
                    .flatten()
                    .filter(|w| !w.is_empty())
                    .unwrap_or_else(|| DEFAULT_WORKSPACE.to_string());
                last.insert(*id, (kind.clone(), by));
            }
        }
    }
    let snap = repo.current()?;
    let mut out: Vec<ClaimOut> = last
        .into_iter()
        .filter_map(|(id, (kind, by))| {
            if kind != NoteKind::Claim {
                return None;
            }
            let name = snap
                .entities
                .get(&id)
                .map(|r| r.name.clone())
                .unwrap_or_else(|| id.short());
            Some(ClaimOut {
                entity: id,
                name,
                by,
            })
        })
        .collect();
    out.sort_by(|a, b| a.name.cmp(&b.name).then(a.by.cmp(&b.by)));
    Ok(out)
}

/// Notes hung on an entity (show-def / the other half of a review thread).
pub fn notes_about_entity(repo: &Repo, id: EntityId) -> Result<Vec<OpOut>> {
    Ok(repo
        .store()
        .ops(OpIx(0), true)?
        .into_iter()
        .filter(|(_, e)| {
            matches!(
                &e.op,
                Op::Note {
                    to: NoteTo::Entity(eid),
                    ..
                } if *eid == id
            )
        })
        .map(|(ix, e)| op_out(repo, ix, &e))
        .collect())
}

crates/svc-repo/tests/sync.rs.Text:
//! A changeset moves between two clones with its review state: after `transfer`, the
//! receiving store lists the group's ops with the same verdicts, subjects and times; a
//! second transfer sends nothing; a later op joins the same group and travels alone; the
//! other clone's own addition comes back the same way.

use std::path::Path;

use svc_core::engine::{classify_def, edit_def, rename};
use svc_core::{Intent, Op};
use svc_repo::sync::transfer;
use svc_repo::{Repo, changeset_begin, changeset_end, changeset_reopen, changesets, resolve_changeset};

const HERE: &str = env!("CARGO_MANIFEST_DIR");

fn demo_crate(into: &Path) {
    let src = Path::new(HERE).join("../../demo/config");
    for name in ["Cargo.toml", "config.txt"] {
        std::fs::copy(src.join(name), into.join(name)).unwrap();
    }
    std::fs::create_dir_all(into.join("src")).unwrap();
    std::fs::copy(src.join("src/main.rs"), into.join("src/main.rs")).unwrap();
}

fn rename_to(repo: &Repo, from: &str, to: &str) {
    let id = svc_repo::resolve_entity(repo, from).unwrap();
    repo.mutate(Op::Rename { id, new: to.into() }, None, |repo, cur| repo.amend(cur, rename(repo.store(), cur, id, to)?))
        .unwrap();
}

fn edit(repo: &Repo, entity: &str, definition: &str) {
    let id = svc_repo::resolve_entity(repo, entity).unwrap();
    let cur = repo.current().unwrap();
    let observed = classify_def(repo.store(), repo.langs(), &cur, id, definition.as_bytes()).unwrap();
    let op = Op::EditDef { id, definition: definition.into(), intent: Intent::Refactor };
    repo.mutate(op, Some(observed), |repo, cur| {
        let (next, _) = edit_def(repo.store(), repo.langs(), cur, id, definition.as_bytes())?;
        repo.amend(cur, next)
    })
    .unwrap();
}

/// What both clones must agree on: everything about the group's ops except the op index
/// (each clone's own log position) and the entity id (each clone's own, mapped by path).
fn review_state(repo: &Repo, name: &str) -> Vec<String> {
    let cs = changesets(repo).unwrap().into_iter().find(|c| c.name == name).unwrap();
    cs.ops
        .iter()
        .map(|o| {
            let kind = match o.op {
                Op::Rename { .. } => "rename",
                Op::EditDef { .. } => "edit-def",
                _ => "other",
            };
            format!(
                "{kind} {:?} {:?} {} {:?} {}",
                o.declared,
                o.observed,
                o.flagged,
                o.subject,
                o.at
            )
        })
        .collect()
}

#[test]
fn a_changeset_travels_with_its_review_state_and_only_what_is_new_travels() {
    let (a_dir, b_dir) = (tempfile::tempdir().unwrap(), tempfile::tempdir().unwrap());
    demo_crate(a_dir.path());
    demo_crate(b_dir.path());
    let a = Repo::init(a_dir.path(), Repo::default_langs()).unwrap();
    let b = Repo::init(b_dir.path(), Repo::default_langs()).unwrap();

    let cs = changeset_begin(&a, "reviewed", Intent::Refactor, None, false).unwrap().id;
    rename_to(&a, "read", "read_file");
    edit(&a, "normalize", "fn normalize(s: &str) -> String {\n    s.trim().to_uppercase()\n}");
    changeset_end(&a).unwrap();
    assert_eq!(review_state(&a, "reviewed").len(), 2);
    assert!(changesets(&b).unwrap().is_empty());

    let r = transfer(&a, &b, cs, "a").unwrap();
    assert_eq!(r.sent, 2);
    assert_eq!(r.import.unwrap().diverged_at, None);
    assert!(std::fs::read_to_string(b_dir.path().join("src/main.rs")).unwrap().contains("read_file("));
    assert_eq!(review_state(&a, "reviewed"), review_state(&b, "reviewed"));
    assert_eq!(resolve_changeset(&b, "reviewed").unwrap().id, cs);
    assert_eq!(transfer(&a, &b, cs, "a").unwrap().sent, 0, "nothing new to send");

    // A follow-up joins the same group and is the only thing sent.
    changeset_reopen(&a, cs).unwrap();
    rename_to(&a, "validate", "check");
    changeset_end(&a).unwrap();
    assert_eq!(transfer(&a, &b, cs, "a").unwrap().sent, 1);
    assert_eq!(review_state(&a, "reviewed"), review_state(&b, "reviewed"));

    // The reviewer's own op on b comes back to a.
    changeset_reopen(&b, cs).unwrap();
    rename_to(&b, "parse", "parse_config");
    changeset_end(&b).unwrap();
    assert_eq!(transfer(&b, &a, cs, "b").unwrap().sent, 1);
    assert!(std::fs::read_to_string(a_dir.path().join("src/main.rs")).unwrap().contains("parse_config("));
    let state = review_state(&a, "reviewed");
    assert_eq!(state.len(), 4);
    assert_eq!(state, review_state(&b, "reviewed"));

    // A prefix or a name resolves; an unknown one is refused.
    assert_eq!(resolve_changeset(&a, &cs.short()[..4]).unwrap().id, cs);
    assert!(resolve_changeset(&a, "nope").is_err());
}

#[test]
fn two_ops_of_one_kind_in_one_millisecond_both_travel() {
    use svc_repo::repo::Provenance;
    let (a_dir, b_dir) = (tempfile::tempdir().unwrap(), tempfile::tempdir().unwrap());
    demo_crate(a_dir.path());
    demo_crate(b_dir.path());
    let a = Repo::init(a_dir.path(), Repo::default_langs()).unwrap();
    let b = Repo::init(b_dir.path(), Repo::default_langs()).unwrap();
    let cs = changeset_begin(&a, "same-ms", Intent::Refactor, None, false).unwrap().id;
    let stamp = Provenance { at: 1234, group: Some(cs), workspace: None };
    a.with_provenance(stamp.clone(), || Ok(rename_to(&a, "read", "read_file"))).unwrap();
    assert_eq!(transfer(&a, &b, cs, "a").unwrap().sent, 1);
    a.with_provenance(stamp, || Ok(rename_to(&a, "validate", "check"))).unwrap();
    assert_eq!(transfer(&a, &b, cs, "a").unwrap().sent, 1, "the second same-millisecond rename is not the first");
    assert!(std::fs::read_to_string(b_dir.path().join("src/main.rs")).unwrap().contains("fn check("));
    assert_eq!(transfer(&a, &b, cs, "a").unwrap().sent, 0);
}

#[test]
fn a_mail_changeset_reaches_a_hub_on_another_tree_and_hand_edits_stay_out_of_it() {
    use svc_core::{NoteKind, NoteTo, Op};
    let (a_dir, hub_dir) = (tempfile::tempdir().unwrap(), tempfile::tempdir().unwrap());
    demo_crate(a_dir.path());
    demo_crate(hub_dir.path());
    let a = Repo::init(a_dir.path(), Repo::default_langs()).unwrap();
    let hub = Repo::init(hub_dir.path(), Repo::default_langs()).unwrap();
    // The hub is on a different tree: someone renamed there.
    rename_to(&hub, "read", "read_hub");
    let mail = changeset_begin(&a, "mail", Intent::Refactor, None, false).unwrap().id;
    // A hand edit on a while the mail changeset is open.
    let main_rs = a_dir.path().join("src/main.rs");
    let edited = std::fs::read_to_string(&main_rs).unwrap().replace("fn validate(", "fn validate_edited(");
    std::fs::write(&main_rs, edited).unwrap();
    svc_repo::note(&a, NoteTo::Checkout("supervisor".into()), NoteKind::Note, "landed x").unwrap();
    changeset_end(&a).unwrap();
    let ops = a.store().ops(svc_core::OpIx(0), false).unwrap();
    let absorb = ops.iter().find(|(_, e)| matches!(e.op, Op::Absorb)).expect("the hand edit was absorbed");
    assert_eq!(absorb.1.group, None, "the absorb is the tree's own, not the mail's");
    let note = ops.iter().find(|(_, e)| matches!(e.op, Op::Note { .. })).unwrap();
    assert_eq!(note.1.group, Some(mail));

    let r = transfer(&a, &hub, mail, "a").unwrap();
    assert_eq!(r.sent, 1, "the note alone, onto a tree that is not a's");
    let inbox_ops = hub.store().ops(svc_core::OpIx(0), false).unwrap();
    let (ix, delivered) = inbox_ops.iter().find(|(_, e)| matches!(e.op, Op::Note { .. })).unwrap();
    assert_eq!(delivered.group, Some(mail));
    assert_eq!(hub.redb().op_workspace(*ix).unwrap().as_deref(), Some("a"), "the sender is named");
    assert!(std::fs::read_to_string(hub_dir.path().join("src/main.rs")).unwrap().contains("read_hub("), "the hub's tree is untouched");
}

EditDef.definition:
fn rewrite(
    &mut self,
    b: &BundleEntry,
    cur: &Snapshot,
    engine: impl FnOnce(&Snapshot) -> Result<Snapshot>,
) -> Result<Snapshot> {
    let repo = self.repo;
    let computed = match engine(cur) {
        Ok(next) => next,
        // The engine of the day refuses what it once did (a rename of a use line, say).
        // The record still says what happened: nothing, or these files.
        Err(refused) => {
            if b.files.is_empty() && tree_hash(&rendered(repo, cur)?) != b.after_tree {
                return Err(refused);
            }
            self.from_record.push(b.ix);
            return self.from_files(b, cur);
        }
    };
    if b.files.is_empty() || tree_hash(&rendered(repo, &computed)?) == b.after_tree {
        return Ok(computed);
    }
    self.from_record.push(b.ix);
    self.from_files(b, cur)
}

crates/svc-repo/src/bundle.rs.Text:
//! A history bundle: the op log of one store, written so another checkout of the same tree
//! can replay it into its own store. Typed ops carry themselves; what they cannot carry is
//! resolved on import — entity ids by their path (file, then kind/name from the root
//! down), change ids by the order they are minted — and a hand edit (`Absorb`) carries the
//! files it changed. Every entry names the hash of the tree it left behind, so an import
//! knows at which op, if any, it stopped reproducing the recorded history.
//!
//! `svc history export` writes one; `svc history import` replays one; `demo/history/` keeps
//! the bundles of this repository's own svc-made changes.

use std::collections::BTreeMap;

use serde::{Deserialize, Serialize};
use svc_core::engine::{add_def_at, delete, edit_def, inline, move_def, relocate, render, rename};
use svc_core::{
    ChangeId, ChangeSet, ChangeSetId, EntityId, Error, Kind, NoteTo, Op, OpIx, OpLogEntry, RelPath, Result,
    Snapshot, SnapshotId,
};

use crate::history::{self, op_entity};
use crate::merge;
use crate::repo::{Provenance, Repo};

/// Where an entity sits: its file, then kind and name from the outermost parent down to
/// itself. The same tree ingested twice gives every entity a fresh id; the path is what
/// survives.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct EntityPath {
    pub file: RelPath,
    pub chain: Vec<(Kind, String)>,
}

/// A file a hand edit left: its new bytes (text when UTF-8), or removed.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum FileBody {
    Text(String),
    Bytes(Vec<u8>),
    Removed,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct BundleEntry {
    pub ix: OpIx,
    pub entry: OpLogEntry,
    /// Every entity id the op names, by path in the tree the op started from (the op's own
    /// new entity, for add-def, is absent: its id is minted by the op).
    #[serde(default)]
    pub refs: BTreeMap<EntityId, EntityPath>,
    /// For `Absorb`: the files the hand edit changed.
    #[serde(default)]
    pub files: BTreeMap<RelPath, FileBody>,
    /// blake3 over the rendered tree after this op (sorted path, bytes).
    pub after_tree: String,
    /// The checkout that made it (`None` = the default one).
    #[serde(default)]
    pub workspace: Option<String>,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Bundle {
    /// blake3 of the rendered tree the first entry starts from; an import checks its own.
    pub base_tree: String,
    pub entries: Vec<BundleEntry>,
    /// The changesets the entries belong to, so a replayed op keeps its group's name.
    #[serde(default)]
    pub changesets: Vec<ChangeSet>,
}

#[derive(Clone, Debug, Serialize)]
pub struct ImportReport {
    pub applied: usize,
    /// Ops whose result the engine no longer computes as recorded; the record supplied
    /// the tree instead, so the history still lands as it happened.
    pub from_record: Vec<OpIx>,
    /// First entry whose tree after import differs from the recorded hash even so, if any.
    pub diverged_at: Option<OpIx>,
}

fn tree_hash(files: &BTreeMap<RelPath, Vec<u8>>) -> String {
    let mut h = blake3::Hasher::new();
    for (path, bytes) in files {
        h.update(path.as_str().as_bytes());
        h.update(&[0]);
        h.update(&(bytes.len() as u64).to_le_bytes());
        h.update(bytes);
    }
    h.finalize().to_hex().to_string()
}

fn rendered(repo: &Repo, snap: &Snapshot) -> Result<BTreeMap<RelPath, Vec<u8>>> {
    Ok(render(snap, repo.store(), repo.langs(), false)?.files)
}

fn path_of(snap: &Snapshot, id: EntityId) -> Option<EntityPath> {
    let rec = snap.entities.get(&id)?;
    let mut chain = vec![(rec.kind, rec.name.clone())];
    let mut parent = rec.parent;
    while let Some(p) = parent {
        let pr = snap.entities.get(&p)?;
        chain.push((pr.kind, pr.name.clone()));
        parent = pr.parent;
    }
    chain.reverse();
    Some(EntityPath { file: rec.file.clone(), chain })
}

fn find_by_path(snap: &Snapshot, path: &EntityPath) -> Option<EntityId> {
    snap.entities
        .iter()
        .filter(|(_, r)| r.file == path.file)
        .find(|(id, _)| path_of(snap, **id).as_ref() == Some(path))
        .map(|(id, _)| *id)
}

/// Every entity id an op names besides one it mints itself.
fn named_ids(op: &Op) -> Vec<EntityId> {
    match op {
        Op::Move { id, parent, .. } => std::iter::once(*id).chain(*parent).collect(),
        Op::Extract { id, new_parent, .. } => std::iter::once(*id).chain(*new_parent).collect(),
        Op::AddDef { parent, .. } => parent.iter().copied().collect(),
        _ => op_entity(op).into_iter().collect(),
    }
}

/// The op log from `since` on, with what an import needs beside each entry.
pub fn export(repo: &Repo, since: OpIx) -> Result<Bundle> {
    export_range(repo, since, None)
}

/// [`export`] stopping before `until` (exclusive), for cutting one landing out of a longer log.
pub fn export_range(repo: &Repo, since: OpIx, until: Option<OpIx>) -> Result<Bundle> {
    let mut ops = repo.store().ops(since, false)?;
    if let Some(end) = until {
        ops.retain(|(ix, _)| *ix < end);
    }
    if ops.is_empty() {
        return Err(Error::Other(format!("no ops at or after {}", since.0)));
    }
    export_ops(repo, ops)
}

/// Whether an op is part of a changeset's story: stamped with the group, or a note
/// addressed to it (a review verdict, a claim) — which has no group of its own.
pub fn belongs(e: &OpLogEntry, group: ChangeSetId) -> bool {
    e.group == Some(group) || matches!(&e.op, Op::Note { to: NoteTo::Changeset(id), .. } if *id == group)
}

/// The ops that [`belongs`] to one changeset except those `has` — what a clone that already holds some of the
/// group's ops still lacks. Empty entries when there is nothing to send.
pub fn export_changeset(repo: &Repo, group: ChangeSetId, has: impl Fn(&OpLogEntry) -> bool) -> Result<Bundle> {
    let mut ops = repo.store().ops(OpIx(0), false)?;
    ops.retain(|(_, e)| belongs(e, group) && !has(e));
    if ops.is_empty() {
        let cs = repo.store().get_changeset(group)?;
        return Ok(Bundle { base_tree: String::new(), entries: Vec::new(), changesets: vec![cs] });
    }
    export_ops(repo, ops)
}

fn export_ops(repo: &Repo, ops: Vec<(OpIx, OpLogEntry)>) -> Result<Bundle> {
    let store = repo.store();
    let (_, first) = &ops[0];
    let base = store.get_snapshot(first.before.root)?;
    let base_tree = tree_hash(&rendered(repo, &base)?);
    let mut entries = Vec::with_capacity(ops.len());
    for (ix, e) in &ops {
        let before = store.get_snapshot(e.before.root)?;
        let after = store.get_snapshot(e.after.root)?;
        let after_files = rendered(repo, &after)?;
        let refs = named_ids(&e.op)
            .into_iter()
            .filter_map(|id| path_of(&before, id).map(|p| (id, p)))
            .collect();
        // What the op changed on disk, for every op: an absorb has nothing else, and any
        // other op falls back to it when a later engine no longer computes the same result.
        let before_files = rendered(repo, &before)?;
        let files = changed_files(&before_files, &after_files);
        entries.push(BundleEntry {
            ix: *ix,
            entry: e.clone(),
            refs,
            files,
            after_tree: tree_hash(&after_files),
            workspace: repo.redb().op_workspace(*ix)?.filter(|w| !w.is_empty()),
        });
    }
    let mut changesets = Vec::new();
    for g in entries.iter().filter_map(|b| {
        b.entry.group.or(match &b.entry.op {
            Op::Note {
                to: NoteTo::Changeset(id),
                ..
            } => Some(*id),
            _ => None,
        })
    }) {
        if !changesets.iter().any(|cs: &ChangeSet| cs.id == g)
            && let Ok(cs) = store.get_changeset(g)
        {
            changesets.push(cs);
        }
    }
    Ok(Bundle { base_tree, entries, changesets })
}

/// The files `after` has that `before` did not have with those bytes, and the ones it lost.
fn changed_files(before: &BTreeMap<RelPath, Vec<u8>>, after: &BTreeMap<RelPath, Vec<u8>>) -> BTreeMap<RelPath, FileBody> {
    let mut files = BTreeMap::new();
    for (path, bytes) in after {
        if before.get(path) != Some(bytes) {
            let body = match String::from_utf8(bytes.clone()) {
                Ok(text) => FileBody::Text(text),
                Err(_) => FileBody::Bytes(bytes.clone()),
            };
            files.insert(path.clone(), body);
        }
    }
    for path in before.keys() {
        if !after.contains_key(path) {
            files.insert(path.clone(), FileBody::Removed);
        }
    }
    files
}

struct Import<'a> {
    repo: &'a Repo,
    /// Recorded change id → the one minted here.
    changes: BTreeMap<ChangeId, ChangeId>,
    /// Recorded snapshot id → the one this import produced for it.
    snaps: BTreeMap<SnapshotId, SnapshotId>,
    /// Ops whose result the engine no longer reproduces and the record supplied instead.
    from_record: Vec<OpIx>,
}

impl Import<'_> {
    fn change(&self, c: ChangeId) -> ChangeId {
        *self.changes.get(&c).unwrap_or(&c)
    }

    fn entity(&self, cur: &Snapshot, b: &BundleEntry, id: EntityId) -> Result<EntityId> {
        let path = b.refs.get(&id).ok_or_else(|| {
            Error::Other(format!("op {}: no path recorded for entity {}", b.ix.0, id.short()))
        })?;
        find_by_path(cur, path).ok_or_else(|| {
            Error::Other(format!(
                "op {}: no entity at {} {} in this tree",
                b.ix.0,
                path.file,
                path.chain.iter().map(|(k, n)| format!("{k:?} {n}")).collect::<Vec<_>>().join(" / ")
            ))
        })
    }

    /// The snapshot an op leaves: what the engine computes now, when its tree is the recorded
    /// one; otherwise the recorded files, ingested over the current snapshot — the history
    /// still lands as it happened, and the op is counted as taken from the record.
    fn rewrite(
        &mut self,
        b: &BundleEntry,
        cur: &Snapshot,
        engine: impl FnOnce(&Snapshot) -> Result<Snapshot>,
    ) -> Result<Snapshot> {
        let repo = self.repo;
        let computed = match engine(cur) {
            Ok(next) => next,
            // The engine of the day refuses what it once did (a rename of a use line, say).
            // The record still says what happened: nothing, or these files.
            Err(refused) => {
                if b.files.is_empty() && tree_hash(&rendered(repo, cur)?) != b.after_tree {
                    return Err(refused);
                }
                self.from_record.push(b.ix);
                return self.from_files(b, cur);
            }
        };
        if b.files.is_empty() || tree_hash(&rendered(repo, &computed)?) == b.after_tree {
            return Ok(computed);
        }
        self.from_record.push(b.ix);
        self.from_files(b, cur)
    }

    fn apply(&mut self, b: &BundleEntry) -> Result<()> {
        let repo = self.repo;
        let e = &b.entry;
        // A `checkout` between ops is not an op: the entry names the root it started from,
        // and if that is not where the last op left us, switch there first.
        if let Some(from) = self.snaps.get(&e.before.root).copied() {
            if from != repo.store().root()? {
                history::checkout(repo, from)?;
            }
        }
        // Same-snapshot rewrites: the op with its ids mapped, then the engine call the verb
        // itself makes.
        let cur = repo.current()?;
        match &e.op {
            Op::Rename { id, new } => {
                let id = self.entity(&cur, b, *id)?;
                let op = Op::Rename { id, new: new.clone() };
                let next = self.rewrite(b, &cur, |cur| rename(repo.store(), cur, id, new))?;
                repo.mutate(op, e.observed, |repo, cur| repo.amend(cur, next))?;
            }
            Op::Move { id, parent, ordinal } => {
                let id = self.entity(&cur, b, *id)?;
                let parent = parent.map(|p| self.entity(&cur, b, p)).transpose()?;
                let op = Op::Move { id, parent, ordinal: *ordinal };
                let next = self.rewrite(b, &cur, |cur| move_def(repo.store(), repo.langs(), cur, id, parent, *ordinal))?;
                repo.mutate(op, e.observed, |repo, cur| repo.amend(cur, next))?;
            }
            Op::Relocate { id, file, ordinal } => {
                let id = self.entity(&cur, b, *id)?;
                let op = Op::Relocate { id, file: file.clone(), ordinal: *ordinal };
                let next = self.rewrite(b, &cur, |cur| relocate(cur, repo.store(), id, file.clone(), *ordinal))?;
                repo.mutate(op, e.observed, |repo, cur| repo.amend(cur, next))?;
            }
            Op::Extract { id, new_parent, ordinal } => {
                let id = self.entity(&cur, b, *id)?;
                let new_parent = new_parent.map(|p| self.entity(&cur, b, p)).transpose()?;
                let op = Op::Extract { id, new_parent, ordinal: *ordinal };
                let next = self.rewrite(b, &cur, |cur| move_def(repo.store(), repo.langs(), cur, id, new_parent, Some(*ordinal)))?;
                repo.mutate(op, e.observed, |repo, cur| repo.amend(cur, next))?;
            }
            Op::Inline { id } => {
                let id = self.entity(&cur, b, *id)?;
                let next = self.rewrite(b, &cur, |cur| inline(repo.store(), repo.langs(), cur, id))?;
                repo.mutate(Op::Inline { id }, e.observed, |repo, cur| repo.amend(cur, next))?;
            }
            Op::AddDef { id, parent, ordinal, definition, intent, file } => {
                let parent = parent.map(|p| self.entity(&cur, b, p)).transpose()?;
                let (id, ordinal, intent, file) = (*id, *ordinal, intent.clone(), file.clone());
                let op = Op::AddDef {
                    id,
                    parent,
                    ordinal,
                    definition: definition.clone(),
                    intent: intent.clone(),
                    file: file.clone(),
                };
                let next = self.rewrite(b, &cur, |cur| {
                    add_def_at(
                        repo.store(),
                        repo.langs(),
                        cur,
                        id,
                        parent,
                        file.clone(),
                        ordinal,
                        definition.as_bytes(),
                        intent.clone(),
                    )
                })?;
                repo.mutate(op, e.observed, |repo, cur| repo.amend(cur, next))?;
            }
            Op::Delete { id, intent } => {
                let id = self.entity(&cur, b, *id)?;
                let op = Op::Delete { id, intent: intent.clone() };
                let next = self.rewrite(b, &cur, |cur| delete(cur, repo.store(), id))?;
                repo.mutate(op, e.observed, |repo, cur| repo.amend(cur, next))?;
            }
            Op::EditDef { id, definition, intent } => {
                let id = self.entity(&cur, b, *id)?;
                let op = Op::EditDef { id, definition: definition.clone(), intent: intent.clone() };
                let next = self.rewrite(b, &cur, |cur| {
                    edit_def(repo.store(), repo.langs(), cur, id, definition.as_bytes()).map(|(next, _)| next)
                })?;
                repo.mutate(op, e.observed, |repo, cur| repo.amend(cur, next))?;
            }
            Op::New { change } => {
                let out = history::new(repo)?;
                self.changes.insert(*change, out.change);
            }
            Op::Describe { msg } => {
                history::describe(repo, msg)?;
            }
            Op::Branch { name } => {
                let out = history::branch(repo, name)?;
                if let Some(recorded) = recorded_change(e) {
                    self.changes.insert(recorded, out.change);
                }
            }
            Op::Merge { other } => {
                let other = self.change(*other);
                let out = merge::merge(repo, &other.to_string())?;
                if let Some(recorded) = recorded_change(e) {
                    self.changes.insert(recorded, out.change);
                }
            }
            // Undo and restore both set a recorded view; restore the mapped ids.
            Op::Undo | Op::Restore { .. } => {
                let mut view = repo.view()?;
                if let Some(root) = self.snaps.get(&e.after.root) {
                    view.root = *root;
                }
                // A head is keyed by the change this store gave the mapped snapshot — the
                // recorded change id is the sender's, and a bundle cut after the change began
                // never named it.
                for snap in e.after.heads.values() {
                    if let Some(mapped) = self.snaps.get(snap) {
                        let change = repo.store().get_snapshot(*mapped)?.change;
                        view.heads.insert(change, *mapped);
                    }
                }
                repo.restore_view(&view, e.op.clone())?;
            }
            Op::Resolve { conflict, take } => {
                merge::resolve(repo, *conflict as usize, *take)?;
            }
            Op::Absorb => {
                write_changes(repo.root_dir(), &b.files)?;
                repo.absorb()?;
            }
            Op::Note { to, kind, text } => {
                let to = match to {
                    NoteTo::Entity(id) => NoteTo::Entity(self.entity(&cur, b, *id)?),
                    other => other.clone(),
                };
                repo.mutate(
                    Op::Note {
                        to,
                        kind: kind.clone(),
                        text: text.clone(),
                    },
                    e.observed,
                    |_, cur| Ok(cur.id()),
                )?;
            }
        }
        Ok(())
    }
}

/// The change an op minted: the head that is the op's after root.
fn recorded_change(e: &OpLogEntry) -> Option<ChangeId> {
    e.after.heads.iter().find(|(_, s)| **s == e.after.root).map(|(c, _)| *c)
}

fn write_changes(root: &std::path::Path, files: &BTreeMap<RelPath, FileBody>) -> Result<()> {
    for (path, body) in files {
        let at = root.join(path.as_str());
        match body {
            FileBody::Removed => {
                let _ = std::fs::remove_file(&at);
            }
            FileBody::Text(t) => write_file(&at, t.as_bytes())?,
            FileBody::Bytes(v) => write_file(&at, v)?,
        }
    }
    Ok(())
}

fn write_file(at: &std::path::Path, bytes: &[u8]) -> Result<()> {
    if let Some(dir) = at.parent() {
        std::fs::create_dir_all(dir).map_err(Error::backend)?;
    }
    std::fs::write(at, bytes).map_err(Error::backend)
}

/// Replay `bundle` into `repo`, whose current tree must be the bundle's base. Stops at the
/// first entry that cannot be applied; reports the first whose result differs from the record.
pub fn import(repo: &Repo, bundle: &Bundle) -> Result<ImportReport> {
    // Notes change no tree, so a bundle of nothing else — mail, verdicts, claims — lands on
    // any tree; the base and the recorded trees only bind ops that write.
    let detached = bundle.entries.iter().all(|b| b.entry.before.root == b.entry.after.root);
    // Hand edits in this checkout are its own absorb, stamped now, not the first replayed
    // op's time and group.
    repo.absorb()?;
    let have = tree_hash(&rendered(repo, &repo.current()?)?);
    if !detached && have != bundle.base_tree {
        return Err(Error::Other(format!(
            "this tree is not the bundle's base (tree {}…, bundle starts from {}…)",
            &have[..12],
            &bundle.base_tree[..12]
        )));
    }
    for cs in &bundle.changesets {
        match repo.store().get_changeset(cs.id) {
            Ok(mut have) => {
                // The row this side holds keeps what it has (its own queue entries); the
                // sender's additions join it.
                let mut grew = false;
                for item in &cs.queue {
                    if !have.queue.contains(item) {
                        have.queue.push(item.clone());
                        grew = true;
                    }
                }
                if have.description.is_empty() && !cs.description.is_empty() {
                    have.description = cs.description.clone();
                    grew = true;
                }
                if grew {
                    repo.store().put_changeset(&have)?;
                }
            }
            Err(_) => repo.store().put_changeset(cs)?,
        }
    }
    let mut im = Import { repo, changes: BTreeMap::new(), snaps: BTreeMap::new(), from_record: Vec::new() };
    if let Some(first) = bundle.entries.first() {
        im.snaps.insert(first.entry.before.root, repo.store().root()?);
    }
    let mut diverged_at = None;
    let mut applied = 0;
    for b in &bundle.entries {
        // The op line keeps its recorded time, changeset and checkout.
        let p = Provenance { at: b.entry.at, group: b.entry.group, workspace: b.workspace.clone() };
        repo.with_provenance(p, || im.apply(b))?;
        applied += 1;
        im.snaps.insert(b.entry.after.root, repo.store().root()?);
        if !detached && diverged_at.is_none() {
            let got = tree_hash(&rendered(repo, &repo.current()?)?);
            if got != b.after_tree {
                diverged_at = Some(b.ix);
            }
        }
    }
    Ok(ImportReport { applied, from_record: im.from_record, diverged_at })
}

